import{z as o,x as p,o as l,c as d,q as r,j as s,D as e,d as E,s as n,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"EUV 单次曝光极限","description":"","frontmatter":{"title":"EUV 单次曝光极限","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-single-expose-limit.md","filePath":"litho/euv-single-expose-limit.md","lastUpdated":1791063341000}'),B={name:"litho/euv-single-expose-limit.md"};function h(m,a,D,_,N,u){const t=p("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="euv-单次曝光极限" tabindex="-1">EUV 单次曝光极限 <a class="header-anchor" href="#euv-单次曝光极限" aria-label="Permalink to &quot;EUV 单次曝光极限&quot;">​</a></h1><div class="epigraph"><p>$k_1$ 掉到约 0.3 以下，NILS、随机孔和掩模 3D 一起到墙。单次不是「EUV 就能无限缩」，再往下是多重 EUV 或抬 NA。</p><footer>—— 对照 Mack $k_1$ 与 NILS；ASML 对 0.33 单次 vs High-NA / 多重的公开讨论</footer></div><p><a href="/litho/euv-layers-per-node">上一课</a>决定哪些层上 EUV。缺口是单次能走多远：0.33 NA、13.5 nm 的瑞利墙，再叠加随机、M3D 和掩模粗糙。高 NA 的产能与经济是否值得为这堵墙买单，留给<a href="/litho/high-na-throughput-economics">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>层数课把最紧层派给 EUV 单次。物理上 \\(CD=k_1\\lambda/\\mathrm{NA}\\)，0.33 NA 下 \\(k_1\\approx 0.4\\) 对应大约 16 nm 半节距量级；\\(k_1\\) 再往 0.3 走，TCC 对关键衍射级的传递变弱，NILS 掉，剂量要涨才能压随机，光源和 pellicle 先告急。孔比线更早死，因为二维缺陷对泊松更敏感。M3D 的 BF 分裂在低 \\(k_1\\) 下占满焦深。掩模粗糙经高 MEEF 放大。</p><p><span class="marginnote">数字代入：\\(CD=k_1\\lambda/\\mathrm{NA}\\)，取 \\(k_1=0.4\\)、\\(\\lambda=13.5\\) nm、\\(\\mathrm{NA}=0.33\\)，半节距约 \\(16\\) nm；\\(k_1\\) 挤到 \\(0.3\\) 就只剩约 \\(12\\) nm。但每挤掉 \\(0.1\\) 的 \\(k_1\\)，NILS 与剂量余量同步恶化，涨剂量又打产能——这就是墙难推的原因。</span></p><p>缺口是把「单次极限」写成这些机制的交集，而不是报一个广告节距。极限随胶、照明和缺陷规格变，故本课写墙的结构，不写某代保证半节距。</p><p><span class="marginnote">浸没在 \\(k_1\\sim 0.3\\) 靠水 NA=1.35 和多重图形续命。EUV 单次的墙更早碰到光子统计，因为每毫焦的光子数少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>判据并行：NILS 下限、随机失效率（孔缺失、桥）、公共焦深、掩模 LER 传递、pellicle 指纹。任一先越界即单次出局。出路三条：加剂量（产能↓）、EUV 双重/切割（层数与套刻↑）、High-NA（场切半、经济下一课）。SMO 和低 n 吸收体是把墙往后推几纳米，不是取消墙。</p><p>与转印：即使空中像勉强过，薄胶转印的缺陷放大可能先把单次判死。极限是成像×集成。</p><h3 id="孔阵列是更早的墙" tabindex="-1">孔阵列是更早的墙 <a class="header-anchor" href="#孔阵列是更早的墙" aria-label="Permalink to &quot;孔阵列是更早的墙&quot;">​</a></h3><p>线可以用偶极把 NILS 抬回；孔是二维，照明更接近环或四极，光子事件摊在面积上，缺失率对剂量更陡。单次极限往往先在孔层报到，线层还能再走一档 \\(k_1\\)。层数课把孔与线分开插入，原因在此，不是两种胶的口味问题。</p><p><span class="marginnote">把光子数想成投票：线是一维的，选票集中在一条窄带里；孔是二维的，同样多选票摊在一小块面积上。摊得越开，每块小格子的票数越抖，「某个孔没开」这种个别意外就越先出现——所以孔层总比线层早撞墙。</span></p>',14)),(l(),s(A,null,{default:e(()=>[n(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20K1%5B%22k1%20%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20NILS%5B%22NILS%20%E6%8E%89%22%5D%0A%20%20K1%20--%3E%20STO%5B%22%E9%9A%8F%E6%9C%BA%E7%BC%BA%E9%99%B7%E5%8D%87%22%5D%0A%20%20K1%20--%3E%20M3D%5B%22BF%20%E5%88%86%E8%A3%82%E5%8D%A0%E6%BB%A1%20DOF%22%5D%0A%20%20NILS%20--%3E%20WALL%5B%22%E5%8D%95%E6%AC%A1%E5%A2%99%22%5D%0A%20%20STO%20--%3E%20WALL%0A%20%20M3D%20--%3E%20WALL%0A%20%20WALL%20--%3E%20HNA%5B%22High-NA%20%E6%88%96%E5%A4%9A%E9%87%8D%20EUV%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[E("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"部分相干下，关键级对的相干传递随 \\(k_1\\) 掉。NILS 低则阈值附近的边沿对剂量和焦点更敏感，随机涨落更容易过打印阈值。92 eV 光子稀疏，CAR 放大或金属吸收只能把工作点在 RLS 上滑动。0.55 NA 把同一 \\(k_1\\) 对应的 CD 缩小，墙被挪到更小节距，但焦深、半场拼接和光子预算另开新墙——不是免费。",-1)),(l(),s(A,null,{default:e(()=>[n(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20OUT%5B%22%E5%8D%95%E6%AC%A1%E5%87%BA%E5%B1%80%E5%90%8E%22%5D%20--%3E%20DOSE%5B%22%E5%87%BA%E8%B7%AF%E4%B8%80%3A%20%E5%8A%A0%E5%89%82%E9%87%8F%22%5D%0A%20%20OUT%20--%3E%20DP%5B%22%E5%87%BA%E8%B7%AF%E4%BA%8C%3A%20EUV%20%E5%8F%8C%E9%87%8D%20%2F%20%E5%88%87%E5%89%B2%22%5D%0A%20%20OUT%20--%3E%20HNA%5B%22%E5%87%BA%E8%B7%AF%E4%B8%89%3A%20High-NA%22%5D%0A%20%20DOSE%20--%3E%20T1%5B%22%E4%BA%A7%E8%83%BD%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DP%20--%3E%20T2%5B%22%E5%B1%82%E6%95%B0%E4%B8%8E%E5%A5%97%E5%88%BB%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HNA%20--%3E%20T3%5B%22%E5%8D%8A%E5%9C%BA%E6%8B%BC%E6%8E%A5%E4%B8%8E%E7%84%A6%E6%B7%B1%E6%96%B0%E8%B4%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>这张图回答的是：单次出局之后三条出路各欠什么账——没有免费的一条，只有按层挑代价最便宜的组合。</p><p><span class="marginnote">Mack 的 \\(k_1\\) 成像图在 EUV 仍适用；额外的轴是随机 Z 因子和 M3D。三轴同时碰到才是工程极限。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 High-NA 的 wph 和晶圆成本算完，下一课才写产能与经济。不重写双重图形的套刻细节。出处：Mack；ASML 0.33 vs High-NA；Naulleau 随机；Finders M3D。</p><p><span class="marginnote">初学者容易把「单次极限」记成一个固定节距数字。实际上它随胶灵敏度、照明方式与失效率目标移动：换一版更敏的胶、放宽孔缺失率，墙都会挪几纳米。本课给的是墙的结构，不是可以抄走的房价。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单次极限是 NILS、随机、M3D 和掩模粗糙的交集，不是单一瑞利数字。</li><li>出路是加剂量、多重 EUV 或抬 NA；SMO 只推移。</li><li>下一课：抬 NA 的产能和经济，并交接到掩模制造课程。</li><li>出处：Mack；ASML；Naulleau；Finders。</li></ul>',7))])}const S=o(B,[["render",h]]);export{k as __pageData,S as default};
